SELECT '==GRADE_GRADES_HISTORY CON NOTAS NO-NULL PARA ITEMS DELETED (1766, 1842, 1843, 1844, 1845, 1928, 2049, 2435, 2785, 3094) ==' as '';
SELECT gh.action, gh.oldid AS gg_id, gh.itemid, gh.userid, u.firstname, u.lastname, gh.finalgrade, gh.rawgrade, from_unixtime(gh.timemodified) dt FROM isi_grade_grades_history gh LEFT JOIN isi_user u ON u.id = gh.userid WHERE gh.itemid IN (SELECT id FROM (SELECT 1766 AS id UNION SELECT 1842 UNION SELECT 1843 UNION SELECT 1844 UNION SELECT 1845 UNION SELECT 1928 UNION SELECT 2049 UNION SELECT 2435 UNION SELECT 2785 UNION SELECT 3094) x WHERE id IN (SELECT id FROM isi_grade_items WHERE courseid = 74)) AND gh.finalgrade IS NOT NULL AND gh.finalgrade >= 0 ORDER BY gh.userid, gh.timemodified;
SELECT '==DISTINCT ITEM IDS QUE TUVIERON NOTAS EN HISTORIAL ==' as '';
SELECT DISTINCT gh.itemid, gi.itemname, gi.iteminstance FROM isi_grade_grades_history gh LEFT JOIN isi_grade_items gi ON gi.id = gh.itemid WHERE gh.itemid IN (SELECT id FROM (SELECT 1766 AS id UNION SELECT 1842 UNION SELECT 1843 UNION SELECT 1844 UNION SELECT 1845 UNION SELECT 1928 UNION SELECT 2049 UNION SELECT 2435 UNION SELECT 2785 UNION SELECT 3094) x WHERE id IN (SELECT id FROM isi_grade_items WHERE courseid = 74));
SELECT '==POR ESTUDIANTE: CUAL ES LA ULTIMA NOTA NO-NULL POR ITEM ==' as '';
SELECT t.itemid, t.userid, u.firstname, u.lastname, t.finalgrade, t.dt FROM (SELECT gh.itemid, gh.userid, gh.finalgrade, from_unixtime(gh.timemodified) dt, ROW_NUMBER() OVER (PARTITION BY gh.itemid, gh.userid ORDER BY gh.timemodified DESC) AS rn FROM isi_grade_grades_history gh WHERE gh.itemid IN (SELECT id FROM (SELECT 1766 AS id UNION SELECT 1842 UNION SELECT 1843 UNION SELECT 1844 UNION SELECT 1845 UNION SELECT 1928 UNION SELECT 2049 UNION SELECT 2435 UNION SELECT 2785 UNION SELECT 3094) x WHERE id IN (SELECT id FROM isi_grade_items WHERE courseid = 74)) AND gh.finalgrade IS NOT NULL AND gh.finalgrade >= 0) t JOIN isi_user u ON u.id = t.userid WHERE t.rn = 1 ORDER BY t.itemid, t.userid;
